@Transactional(readOnly = true)
public RegionPlayoutDecisionResponse regionPlayoutDecision(String channelId, String regionCode, OffsetDateTime at) {
    var channel = repo.findChannel(channelId).orElseThrow(404);
    long atMs = toMs(at);
    Optional<OverrideRow> override = selectActiveOverrideAt(channelId, atMs);
    if (override.isPresent()) {
        OverrideRow hit = override.get();
        return new RegionPlayoutDecisionResponse(channelId, regionCode, at, hit.assetId(),
                DecisionSource.EMERGENCY, null, null, null, null, hit.overrideKey(), null, null, null);
    }
    LocalDate businessDay = at.atZoneSameInstant(ZONE).toLocalDate();
    Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
    if (publication.isEmpty()) {
        return regionFallback(channelId, regionCode, at, channel.fallbackAssetId(), FallbackReason.NO_PUBLISHED_SCHEDULE);
    }
    Optional<PublicationSegmentRow> segment = repo.findPublicationSegmentAt(publication.get().id(), atMs);
    if (segment.isEmpty()) {
        return regionFallback(..., GAP);
    }
    PublicationSegmentRow hit = segment.get();
    // 区域插播：窗口内使用发布快照素材
    Optional<PublicationRegionRow> spliceRow = repo.findSpliceRowAt(publication.get().id(), hit.segmentId(), regionCode, atMs);
    if (spliceRow.isPresent()) {
        PublicationRegionRow row = spliceRow.get();
        GrantRow spliceGrant = repo.findGrant(row.grantId()).orElseThrow(SNAPSHOT_INCOMPLETE);
        if (!spliceGrant.revoked()) {
            return new RegionPlayoutDecisionResponse(channelId, regionCode, at, row.assetId(),
                    DecisionSource.SPLICE, null, null, publication.get().id(), hit.segmentId(), null,
                    row.grantId(), atMs(row.spliceStartMs()), atMs(row.spliceEndMs()));
        }
        // 插播授权已撤销 → 回退主素材
        return mainAssetDecision(channel, regionCode, at, publication.get(), hit,
                SpliceFallbackReason.SPLICE_GRANT_REVOKED);
    }
    Optional<PublicationRegionRow> base = repo.findBaseRegionRow(publication.get().id(), hit.segmentId(), regionCode);
    SpliceFallbackReason spliceReason = base.map(b -> SpliceFallbackReason.valueOf(b.fallbackReason()))
            .orElse(SpliceFallbackReason.NO_SPLICE_CONFIG);
    return mainAssetDecision(channel, regionCode, at, publication.get(), hit, spliceReason);
}

private RegionPlayoutDecisionResponse mainAssetDecision(channel, regionCode, at, publication, segment, spliceReason) {
    GrantRow grant = repo.findGrant(segment.grantId()).orElseThrow(SNAPSHOT_INCOMPLETE);
    if (grant.revoked()) {
        return new RegionPlayoutDecisionResponse(channelId, regionCode, at, channel.fallbackAssetId(),
                DecisionSource.FALLBACK, FallbackReason.GRANT_REVOKED, spliceReason,
                publication.id(), segment.segmentId(), null, null, null, null);
    }
    return new RegionPlayoutDecisionResponse(channelId, regionCode, at, segment.assetId(),
            DecisionSource.PROGRAM, null, spliceReason, publication.id(), segment.segmentId(), null,
            segment.grantId(), null, null);
}
