                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("SPLICE_WINDOW_OVERLAP"));

        // 端点相接合法：10:15-10:30 与 10:30-10:45
        putJson("/api/channels/" + channel + "/drafts/" + DAY,
                        draftBody("req-" + p + "-s4", 1,
