                .andExpect(jsonPath("$.segments[0].splices.length()").value(2));

        // 422：插播窗口超出条目窗口
        putJson("/api/channels/" + channel + "/drafts/" + DAY,
                        draftBody("req-" + p + "-s5", 2,
                                segment(p + "seg-1", p + "movie", T_10, T_11,
